# nth_fib_mod :: (10, 1000)
def nth_fib_mod(n, m):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, (a + b) % m
    return a

if __name__ == '__main__':
    print(nth_fib_mod((10, 1000)))

